import React, { useState } from "react";
import { motion } from "framer-motion";

export default function App() {
  const [dark, setDark] = useState(false);
  const toggleTheme = () => setDark(!dark);

  return (
    <div className={dark ? "bg-neutral-950 text-gray-100" : "bg-neutral-50 text-gray-800"}>

      {/* HERO SECTION */}
      <section className="relative min-h-screen flex flex-col justify-center items-center text-center px-6 overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-indigo-500/30 to-transparent dark:from-fuchsia-500/10 blur-3xl"></div>

        <motion.h1
          initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}
          className="text-5xl font-bold tracking-tight">
          Khalil Braham
        </motion.h1>
        <p className="opacity-80 mt-3 text-lg">Generative AI • Discrete Science • Drug Development</p>
        <div className="mt-6 flex gap-4">
          <button onClick={toggleTheme} className="px-4 py-2 text-sm rounded-full bg-indigo-600 text-white hover:bg-indigo-700 transition">{dark ? "Light Mode" : "Dark Mode"}</button>
          <a href="#vision" className="px-4 py-2 text-sm rounded-full bg-neutral-800 text-white hover:bg-neutral-900 dark:bg-neutral-200 dark:text-neutral-800 transition">Research Vision</a>
        </div>
      </section>

      {/* ABOUT */}
      <section id="about" className="max-w-4xl mx-auto py-24 px-6">
        <motion.h2 initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} className="text-3xl font-semibold">
          About Me
        </motion.h2>
        <p className="mt-4 leading-relaxed opacity-90">
          I am a researcher at <a href="https://www.polytechnique.edu/" className="underline">École Polytechnique</a> and <a href="https://www.inria.fr/en/centre-inria-saclay" className="underline">Inria Saclay</a>, working on generative models for discrete scientific structures such as molecules and symbolic biological systems.
          In collaboration with <a href="https://www.sanofi.com/" className="underline">Sanofi</a>, I align large language models for pharmacological reasoning.
        </p>
      </section>

      {/* VISION */}
      <section id="vision" className="max-w-4xl mx-auto py-24 px-6">
        <h2 className="text-3xl font-semibold">Research Vision</h2>
        <p className="mt-4 leading-relaxed opacity-90">
          My ambition is to build autonomous scientific agents capable of proposing experiments, guiding molecule refinement, and interacting with biological literature.
        </p>
      </section>

      {/* FOOTER */}
      <footer className="py-12 text-center opacity-60 text-sm">
        © {new Date().getFullYear()} Khalil Braham — All Rights Reserved
      </footer>

    </div>
  );
}
